changeSet.sql:
CREATE OR REPLACE FUNCTION modeling_reject_implementation_command_receipt_mutation()
RETURNS trigger
LANGUAGE plpgsql
AS $function$
BEGIN
    RAISE EXCEPTION 'MODEL_IMPLEMENTATION_COMMAND_RECEIPT_APPEND_ONLY'
        USING ERRCODE = '55000';
END;
$function$;

rollback.sql:
DO $$
BEGIN
    LOCK TABLE modeling_model_implementation_command_receipt IN ACCESS EXCLUSIVE MODE;
    IF EXISTS (SELECT 1 FROM modeling_model_implementation_command_receipt) THEN
        RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_IMPLEMENTATION_COMMAND_RECEIPT_DATA_EXISTS';
    END IF;
END $$;
